13		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
14		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
15		"github.com/entireio/cli/cmd/entire/cli/logging"
16		"github.com/entireio/cli/cmd/entire/cli/paths"
17		"github.com/entireio/cli/cmd/entire/cli/strategy"
18		"github.com/entireio/cli/cmd/entire/cli/transcript/compact"
19		"github.com/entireio/cli/cmd/entire/cli/versioninfo"
20		"github.com/entireio/cli/redact"
21		"github.com/go-git/go-git/v6"
22		"github.com/go-git/go-git/v6/plumbing"
23		"github.com/go-git/go-git/v6/plumbing/object"
24		"github.com/spf13/cobra"
25	)
26	
27	func newMigrateCmd() *cobra.Command {
28		var checkpointsFlag string
29		var forceFlag bool
30	
31		cmd := &cobra.Command{
32			Use:    "migrate",
33			Short:  "Migrate Entire data to newer formats",
34			Long:   `Migrate Entire data to newer formats. Currently supports migrating v1 checkpoints to v2.`,
35			Hidden: true,
36			RunE: func(cmd *cobra.Command, _ []string) error {
37				if checkpointsFlag == "" {
38					return cmd.Help()
39				}
40				if checkpointsFlag != "v2" {
41					return fmt.Errorf("unsupported checkpoints version: %q (only \"v2\" is supported)", checkpointsFlag)
42				}
43	
44				ctx := cmd.Context()
45	
46				if _, err := paths.WorktreeRoot(ctx); err != nil {
47					cmd.SilenceUsage = true
48					fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
49					return NewSilentError(errors.New("not a git repository"))
50				}
51	
52				logging.SetLogLevelGetter(GetLogLevel)
53				if initErr := logging.Init(ctx, ""); initErr != nil {
54					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not initialize logging: %v\n", initErr)
55				} else {
56					defer logging.Close()
57				}
58				return runMigrateCheckpointsV2(ctx, cmd, forceFlag)
59			},
60		}
61	
62		cmd.Flags().StringVar(&checkpointsFlag, "checkpoints", "", "Target checkpoint format version (e.g., \"v2\")")
63		cmd.Flags().BoolVar(&forceFlag, "force", false, "Force re-migration of all checkpoints, overwriting existing v2 data")
64	
65		return cmd
66	}
67	
68	type migrateResult struct {
69		migrated int
70		skipped  int
71		failed   int
72	}
73	
74	func runMigrateCheckpointsV2(ctx context.Context, cmd *cobra.Command, force bool) error {
75		repo, err := strategy.OpenRepository(ctx)
76		if err != nil {
77			cmd.SilenceUsage = true
78			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
79			return NewSilentError(err)
80		}
81	
82		v1Store := checkpoint.NewGitStore(repo)
83		v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
84		out := cmd.OutOrStdout()
85	
86		result, err := migrateCheckpointsV2(ctx, repo, v1Store, v2Store, out, force)
87		if err != nil {
88			return err
89		}
90	
91		fmt.Fprintf(out, "\nMigration complete: %d migrated, %d skipped, %d failed\n",
92			result.migrated, result.skipped, result.failed)
93	
94		if result.failed > 0 {
95			fmt.Fprintf(out, "%d checkpoint(s) failed to migrate. Check .entire/logs/ for details.\n", result.failed)
96			return NewSilentError(fmt.Errorf("%d checkpoint(s) failed to migrate", result.failed))
97		}
98	
99		return nil
100	}
101	
102	var (
103		errAlreadyMigrated          = errors.New("already migrated")
104		errTranscriptNotGeneratable = errors.New("transcript.jsonl could not be generated")
105	)
106	
107	const migrateRemoteName = "origin"
108	
109	func migrateCheckpointsV2(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, out io.Writer, force bool) (*migrateResult, error) {
110		v1List, err := v1Store.ListCommitted(ctx)
111		if err != nil {
112			return nil, fmt.Errorf("failed to list v1 checkpoints: %w", err)
113		}
114	
115		if len(v1List) == 0 {
116			fmt.Fprintln(out, "Nothing to migrate: no v1 checkpoints found")
117			return &migrateResult{}, nil
118		}
119	
120		if force {
121			fmt.Fprintln(out, "Force-migrating v1 checkpoints to v2 (overwriting existing)...")
122		} else {
123			fmt.Fprintln(out, "Migrating v1 checkpoints to v2...")
124		}
125		total := len(v1List)
126		result := &migrateResult{}
127	
128		for i, info := range v1List {
129			prefix := fmt.Sprintf("  [%d/%d] Migrating checkpoint %s...", i+1, total, info.CheckpointID)
130	
131			if migrateErr := migrateOneCheckpoint(ctx, repo, v1Store, v2Store, info, out, prefix, force); migrateErr != nil {
132				switch {
133				case errors.Is(migrateErr, errAlreadyMigrated):
134					fmt.Fprintf(out, "%s skipped (already in v2)\n", prefix)
135					result.skipped++
136				case errors.Is(migrateErr, errTranscriptNotGeneratable):
137					fmt.Fprintf(out, "%s in v2, but %s\n", prefix, migrateErr.Error())
138					result.skipped++
139				default:
140					fmt.Fprintf(out, "%s failed\n", prefix)
141					logging.Error(ctx, "checkpoint migration failed",
142						slog.String("checkpoint_id", string(info.CheckpointID)),
143						slog.String("error", migrateErr.Error()),
144					)
145					result.failed++
146				}
147				continue
148			}
149	
150			result.migrated++
151		}
152	
153		return result, nil
154	}
155	
156	func migrateOneCheckpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, out io.Writer, prefix string, force bool) error {
157		existing, err := v2Store.ReadCommitted(ctx, info.CheckpointID)
158		if err != nil {
159			return fmt.Errorf("failed to check v2 for checkpoint %s: %w", info.CheckpointID, err)
160		}
161	
162		// Already in v2 — when not forcing, check if any aspect of sessions are missing and backfill
163		if existing != nil && !force {
164			repaired, repairErr := repairPartialV2Checkpoint(ctx, repo, v1Store, v2Store, info, existing)
165			if repairErr != nil {
166				return repairErr
167			}
168	
169			currentV2, readCurrentErr := v2Store.ReadCommitted(ctx, info.CheckpointID)
170			if readCurrentErr != nil {
171				return fmt.Errorf("failed to re-read v2 checkpoint %s: %w", info.CheckpointID, readCurrentErr)
172			}
173			if currentV2 == nil {
174				return fmt.Errorf("v2 checkpoint %s disappeared during migration", info.CheckpointID)
175			}
176	
177			backfillErr := backfillCompactTranscripts(ctx, v1Store, v2Store, info, currentV2, out, prefix)
178			if errors.Is(backfillErr, errAlreadyMigrated) && repaired {
179				fmt.Fprintf(out, "%s repaired partial v2 checkpoint state\n", prefix)
180				return nil
181			}
182			if errors.Is(backfillErr, errTranscriptNotGeneratable) && repaired {
183				fmt.Fprintf(out, "%s repaired partial v2 checkpoint state (compact transcript not generated)\n", prefix)
184				return nil
185			}
186			return backfillErr
187		}
188	
189		summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
190		if err != nil {
191			return fmt.Errorf("failed to read v1 summary: %w", err)
192		}
193		if summary == nil {
194			return fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
195		}
196	
197		compactFailed := false
198		shouldCopyTaskMetadata := false
199	
200		for sessionIdx := range len(summary.Sessions) {
201			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
202			if readErr != nil {
203				return fmt.Errorf("failed to read v1 session %d: %w", sessionIdx, readErr)
204			}
205			if content.Metadata.IsTask {
206				shouldCopyTaskMetadata = true
207			}
208	
209			opts := buildMigrateWriteOpts(content, info)
210	
211			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
212			if compacted != nil {
213				opts.CompactTranscript = compacted
214				opts.CompactTranscriptStart = computeCompactOffset(ctx, content.Transcript, compacted, content.Metadata)
215			} else if len(content.Transcript) > 0 {
216				compactFailed = true
217			}
218	
219			if writeErr := v2Store.WriteCommitted(ctx, opts); writeErr != nil {
220				return fmt.Errorf("failed to write v2 session %d: %w", sessionIdx, writeErr)
221			}
222		}
223	
224		// Copy task metadata trees from v1 to v2 /full/current
225		if shouldCopyTaskMetadata {
226			if taskErr := copyTaskMetadataToV2(ctx, repo, v1Store, v2Store, info.CheckpointID, summary); taskErr != nil {
227				logging.Warn(ctx, "failed to copy task metadata to v2",
228					slog.String("checkpoint_id", string(info.CheckpointID)),
229					slog.String("error", taskErr.Error()),
230				)
231			}
232		}
233	
234		if compactFailed {
235			fmt.Fprintf(out, "%s done (compact transcript not generated)\n", prefix)
236		} else {
237			fmt.Fprintf(out, "%s done\n", prefix)
238		}
239	
240		return nil
241	}
242	
243	func repairPartialV2Checkpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary) (bool, error) {
244		repaired := false
245	
246		// Spot-check already present sessions: ensure required /full/current artifacts exist.
247		existingSessionCount := len(v2Summary.Sessions)
248		for sessionIdx := range existingSessionCount {
249			ok, checkErr := hasCurrentFullSessionArtifacts(repo, v2Store, info.CheckpointID, sessionIdx)
250			if checkErr != nil {
251				return false, fmt.Errorf("failed to check v2 session %d artifacts: %w", sessionIdx, checkErr)
252			}
253			if ok {
254				continue
255			}
256	
257			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
258			if readErr != nil {
259				return false, fmt.Errorf("failed to read v1 session %d while repairing v2: %w", sessionIdx, readErr)
260			}
261	
262			updateOpts := checkpoint.UpdateCommittedOptions{
263				CheckpointID: info.CheckpointID,
264				SessionID:    content.Metadata.SessionID,
265				// content.Transcript was read from v1 checkpoint storage and is
266				// already redacted at write time.
267				Transcript: redact.AlreadyRedacted(content.Transcript),
268				Prompts:    checkpoint.SplitPromptContent(content.Prompts),
269				Agent:      content.Metadata.Agent,
270			}
271			if compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata); compacted != nil {
272				updateOpts.CompactTranscript = compacted
273			}
274	
275			if updateErr := v2Store.UpdateCommitted(ctx, updateOpts); updateErr != nil {
276				return false, fmt.Errorf("failed to repair v2 session %d: %w", sessionIdx, updateErr)
277			}
278			repaired = true
279		}
280	
281		return repaired, nil
282	}
283	
284	func hasCurrentFullSessionArtifacts(repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, sessionIdx int) (bool, error) {
285		_, rootTreeHash, err := v2Store.GetRefState(plumbing.ReferenceName(paths.V2FullCurrentRefName))
286		if err != nil {
287			return false, nil //nolint:nilerr // Missing /full/current ref means required artifacts are absent.
288		}
289	
290		rootTree, err := repo.TreeObject(rootTreeHash)
291		if err != nil {
292			return false, fmt.Errorf("failed to read /full/current tree: %w", err)
293		}
294	
295		sessionPath := fmt.Sprintf("%s/%d", cpID.Path(), sessionIdx)
296		sessionTree, err := rootTree.Tree(sessionPath)
297		if err != nil {
298			return false, nil //nolint:nilerr // Missing session path means artifacts are absent, not a hard error.
299		}
300	
301		hasTranscript := false
302		for _, entry := range sessionTree.Entries {
303			if entry.Name == paths.V2RawTranscriptFileName || strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+".") {
304				hasTranscript = true
305				break
306			}
307		}
308		if !hasTranscript {
309			return false, nil
310		}
311	
312		if _, err := sessionTree.File(paths.V2RawTranscriptHashFileName); err != nil {
313			return false, nil //nolint:nilerr // Missing content hash indicates incomplete /full/current artifacts.
314		}
315	
316		return true, nil
317	}
318	
319	// backfillCompactTranscripts checks sessions in an already-migrated v2 checkpoint
320	// for missing transcript.jsonl and attempts to generate + write them from v1 data.
321	// Returns errAlreadyMigrated if all sessions already have compact transcripts.
322	func backfillCompactTranscripts(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary, out io.Writer, prefix string) error {
323		// Find sessions missing transcript.jsonl
324		var needsBackfill []int
325		for i, session := range v2Summary.Sessions {
326			if session.Transcript == "" {
327				needsBackfill = append(needsBackfill, i)
328			}
329		}
330	
331		if len(needsBackfill) == 0 {
332			return errAlreadyMigrated
333		}
334	
335		backfilled := 0
336		var lastAgent string
337	
338		for _, sessionIdx := range needsBackfill {
339			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
340			if readErr != nil {
341				logging.Warn(ctx, "transcript.jsonl backfill: could not read v1 session",
342					slog.String("checkpoint_id", string(info.CheckpointID)),
343					slog.Int("session_index", sessionIdx),
344					slog.String("error", readErr.Error()),
345				)
346				continue
347			}
348	
349			if content.Metadata.Agent != "" {
350				lastAgent = string(content.Metadata.Agent)
351			}
352	
353			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
354			if compacted == nil {
355				// tryCompactTranscript already logs for no-agent and compact-error cases;
356				// log the empty-transcript case here.
357				if len(content.Transcript) == 0 {
358					logging.Warn(ctx, "transcript.jsonl backfill: empty transcript in v1",
359						slog.String("checkpoint_id", string(info.CheckpointID)),
360						slog.Int("session_index", sessionIdx),
361					)
362				}
363				continue
364			}
365	
366			updateErr := v2Store.UpdateCommitted(ctx, checkpoint.UpdateCommittedOptions{
367				CheckpointID:      info.CheckpointID,
368				SessionID:         content.Metadata.SessionID,
369				CompactTranscript: compacted,
370			})
371			if updateErr != nil {
372				logging.Warn(ctx, "transcript.jsonl backfill: failed to write to v2",
373					slog.String("checkpoint_id", string(info.CheckpointID)),
374					slog.Int("session_index", sessionIdx),
375					slog.String("error", updateErr.Error()),
376				)
377				continue
378			}
379	
380			backfilled++
381		}
382	
383		if backfilled == 0 {
384			if lastAgent != "" {
385				return fmt.Errorf("%w: agent %q", errTranscriptNotGeneratable, lastAgent)
386			}
387			return fmt.Errorf("%w: no agent type in metadata", errTranscriptNotGeneratable)
388		}
389	
390		fmt.Fprintf(out, "%s added transcript.jsonl for %d session(s)\n", prefix, backfilled)
391	
392		return nil
393	}
394	
395	func buildMigrateWriteOpts(content *checkpoint.SessionContent, info checkpoint.CommittedInfo) checkpoint.WriteCommittedOptions {
396		m := content.Metadata
397	
398		prompts := checkpoint.SplitPromptContent(content.Prompts)
399	
400		return checkpoint.WriteCommittedOptions{
401			CheckpointID: info.CheckpointID,
402			SessionID:    m.SessionID,
403			Strategy:     m.Strategy,
404			Branch:       m.Branch,
405			// content.Transcript comes from persisted checkpoint storage and is
406			// already redacted.
407			Transcript:                  redact.AlreadyRedacted(content.Transcript),
408			Prompts:                     prompts,
409			FilesTouched:                m.FilesTouched,
410			CheckpointsCount:            m.CheckpointsCount,
411			Agent:                       m.Agent,
412			Model:                       m.Model,
413			TurnID:                      m.TurnID,
414			TokenUsage:                  m.TokenUsage,
415			SessionMetrics:              m.SessionMetrics,
416			InitialAttribution:          m.InitialAttribution,
417			Summary:                     m.Summary,
418			CheckpointTranscriptStart:   m.GetTranscriptStart(),
419			TranscriptIdentifierAtStart: m.TranscriptIdentifierAtStart,
420			IsTask:                      m.IsTask,
421			ToolUseID:                   m.ToolUseID,
422			AuthorName:                  "Entire Migration",
423			AuthorEmail:                 "migration@entire.dev",
424		}
425	}
426	
427	func tryCompactTranscript(ctx context.Context, transcript []byte, m checkpoint.CommittedMetadata) []byte {
428		return compactTranscriptForStartLine(ctx, transcript, m, 0)
429	}
430	
431	func compactTranscriptForStartLine(ctx context.Context, transcript []byte, m checkpoint.CommittedMetadata, startLine int) []byte {
432		if len(transcript) == 0 {
433			return nil
434		}
435		if m.Agent == "" {
436			logging.Warn(ctx, "compact transcript skipped: no agent type in checkpoint metadata",
437				slog.String("checkpoint_id", string(m.CheckpointID)),
438			)
439			return nil
440		}
441	
442		// transcript is read from persisted checkpoint storage and already redacted.
443		compacted, err := compact.Compact(redact.AlreadyRedacted(transcript), compact.MetadataFields{
444			Agent:      string(m.Agent),
445			CLIVersion: versioninfo.Version,
446			StartLine:  startLine,
447		})
448		if err != nil {
449			logging.Warn(ctx, "compact transcript generation failed during migration",
450				slog.String("checkpoint_id", string(m.CheckpointID)),
451				slog.String("agent", string(m.Agent)),
452				slog.String("error", err.Error()),
453			)
454			return nil
455		}
456		if len(compacted) == 0 {
457			logging.Warn(ctx, "transcript.jsonl generation produced no output",
458				slog.String("checkpoint_id", string(m.CheckpointID)),
459				slog.String("agent", string(m.Agent)),
460				slog.Int("input_bytes", len(transcript)),
461			)
462			return nil
463		}
464		return compacted
465	}
466	
467	// computeCompactOffset determines the transcript.jsonl line offset for a checkpoint
468	// by comparing a full compact (startLine=0) against the scoped compact. The difference
469	// is the number of compact lines before this checkpoint's data.
470	func computeCompactOffset(ctx context.Context, fullTranscript, fullCompact []byte, m checkpoint.CommittedMetadata) int {
471		startLine := m.GetTranscriptStart()
472		if startLine == 0 || len(fullTranscript) == 0 || m.Agent == "" {
473			return 0
474		}
475	
476		if len(fullCompact) == 0 {
477			return 0
478		}
479	
480		// fullTranscript is read from persisted checkpoint storage and already redacted.
481		scopedCompact, err := compact.Compact(redact.AlreadyRedacted(fullTranscript), compact.MetadataFields{
482			Agent:      string(m.Agent),
483			CLIVersion: versioninfo.Version,
484			StartLine:  startLine,
485		})
486		if err != nil {
487			logging.Warn(ctx, "compact transcript offset calculation failed during migration",
488				slog.String("checkpoint_id", string(m.CheckpointID)),
489				slog.String("agent", string(m.Agent)),
490				slog.String("error", err.Error()),
491			)
492			return 0
493		}
494		if len(scopedCompact) == 0 {
495			return 0
496		}
497	
498		fullLines := bytes.Count(fullCompact, []byte{'\n'})
499		scopedLines := bytes.Count(scopedCompact, []byte{'\n'})
500		offset := fullLines - scopedLines
501		if offset < 0 {
502			logging.Warn(ctx, "compact transcript offset was negative during migration, defaulting to 0",
503				slog.String("checkpoint_id", string(m.CheckpointID)),
504				slog.Int("full_lines", fullLines),
505				slog.Int("scoped_lines", scopedLines),
506			)
507			return 0
508		}
509		return offset
510	}
511	
512	// copyTaskMetadataToV2 copies task metadata files (subagent transcripts, checkpoint JSONs)
513	// from the v1 branch to the v2 /full/current ref via tree surgery.
514	func copyTaskMetadataToV2(ctx context.Context, repo *git.Repository, _ *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, summary *checkpoint.CheckpointSummary) error {
515		// Resolve the v1 branch tree
516		v1Tree, err := resolveV1CheckpointTree(repo, cpID)
517		if err != nil {
518			return err
519		}
520	
521		// Legacy v1 layout stores task metadata at checkpoint root: <cp>/tasks/<tool-use-id>/...
522		// Prefer attaching this tree to the latest session in v2.
523		if rootTasksTree, rootTasksErr := v1Tree.Tree("tasks"); rootTasksErr == nil {
524			if len(summary.Sessions) > 0 {
525				latestSessionIdx := len(summary.Sessions) - 1
526				if spliceErr := spliceTasksTreeToV2(ctx, repo, v2Store, cpID, latestSessionIdx, rootTasksTree.Hash); spliceErr != nil {
527					return fmt.Errorf("latest session task tree splice failed: %w", spliceErr)
528				}
529			}
530		}
531	
532		for sessionIdx := range len(summary.Sessions) {
533			sessionDir := strconv.Itoa(sessionIdx)
534			sessionTree, sessionErr := v1Tree.Tree(sessionDir)
535			if sessionErr != nil {
536				continue
537			}
538	
539			tasksTree, tasksErr := sessionTree.Tree("tasks")
540			if tasksErr != nil {
541				continue // No tasks directory in this session
542			}
543	
544			if spliceErr := spliceTasksTreeToV2(ctx, repo, v2Store, cpID, sessionIdx, tasksTree.Hash); spliceErr != nil {
545				return fmt.Errorf("session %d task tree splice failed: %w", sessionIdx, spliceErr)
546			}
547		}
548	
549		return nil
550	}
551	
552	// resolveV1CheckpointTree reads the checkpoint subtree from the v1 branch.
553	func resolveV1CheckpointTree(repo *git.Repository, cpID id.CheckpointID) (*object.Tree, error) {
554		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
555		ref, err := repo.Reference(refName, true)
556		if err != nil {
557			// Try remote tracking branch
558			remoteRefName := plumbing.NewRemoteReferenceName(migrateRemoteName, paths.MetadataBranchName)
559			ref, err = repo.Reference(remoteRefName, true)
560			if err != nil {
561				return nil, fmt.Errorf("v1 branch not found: %w", err)
562			}
563		}
564	
565		commit, err := repo.CommitObject(ref.Hash())
566		if err != nil {
567			return nil, fmt.Errorf("failed to get v1 commit: %w", err)
568		}
569	
570		rootTree, err := commit.Tree()
571		if err != nil {
572			return nil, fmt.Errorf("failed to get v1 tree: %w", err)
573		}
574	
575		cpTree, err := rootTree.Tree(cpID.Path())
576		if err != nil {
577			return nil, fmt.Errorf("checkpoint %s not found in v1 tree: %w", cpID, err)
578		}
579	
580		return cpTree, nil
581	}
582	
583	func spliceTasksTreeToV2(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, sessionIdx int, tasksTreeHash plumbing.Hash) error {
584		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
585		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
586		if err != nil {
587			return fmt.Errorf("failed to get v2 ref state: %w", err)
588		}
589		incomingTasksTree, err := repo.TreeObject(tasksTreeHash)
590		if err != nil {
591			return fmt.Errorf("failed to read tasks tree: %w", err)
592		}
593	
594		shardPrefix := string(cpID[:2])
595		shardSuffix := string(cpID[2:])
596		sessionDir := strconv.Itoa(sessionIdx)
597	
598		newRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
599			[]string{shardPrefix, shardSuffix, sessionDir, "tasks"},
600			incomingTasksTree.Entries,
601			checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.MergeKeepExisting},
602		)
603		if err != nil {
604			return fmt.Errorf("tree surgery failed: %w", err)
605		}
606	
607		commitHash, err := checkpoint.CreateCommit(ctx, repo, newRoot, parentHash,
608			fmt.Sprintf("Add task metadata for %s\n", cpID),
609			"Entire Migration", "migration@entire.dev")
610		if err != nil {
611			return fmt.Errorf("failed to create commit: %w", err)
612		}
613	
614		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
615			return fmt.Errorf("failed to update ref %s: %w", refName, err)
616		}
617		return nil
618	}
