189	// updateCommittedFullTranscript replaces the transcript for a specific checkpoint
190	// on /full/current while preserving other checkpoints' transcripts in the tree.
191	func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
192		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
193		if err := s.ensureRef(ctx, refName); err != nil {
194			return fmt.Errorf("failed to ensure /full/current ref: %w", err)
195		}
196	
197		parentHash, rootTreeHash, err := s.GetRefState(refName)
198		if err != nil {
199			return err
200		}
201	
202		basePath := opts.CheckpointID.Path() + "/"
203		checkpointPath := opts.CheckpointID.Path()
204		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
205	
206		// Read existing entries and replace transcript for this checkpoint only
207		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
208		if err != nil {
209			return err
210		}
211	
212		// Ignore precompute if invariants are violated — fall back to fresh chunking.
213		precomputed := opts.PrecomputedBlobs
214		if precomputed != nil && !precomputed.isUsable() {
215			precomputed = nil
216		}
217	
218		// Short-circuit: if the existing raw_transcript_hash.txt already matches
219		// the new transcript's sha256, the existing chunk entries represent the
220		// same content — preserve them and skip chunking + zlib.
221		rawTranscriptPath := sessionPath + paths.V2RawTranscriptFileName
222		rawHashPath := sessionPath + paths.V2RawTranscriptHashFileName
223		var newContentHash string
224		if precomputed != nil {
225			newContentHash = precomputed.ContentHash
226		} else {
227			newContentHash = fmt.Sprintf("sha256:%x", sha256.Sum256(opts.Transcript.Bytes()))
228		}
229		if existing, ok := entries[rawHashPath]; ok {
230			if blob, err := s.repo.BlobObject(existing.Hash); err == nil {
231				if rdr, rerr := blob.Reader(); rerr == nil {
232					existingHash, readErr := io.ReadAll(rdr)
233					_ = rdr.Close()
234					if readErr == nil && string(existingHash) == newContentHash {
235						// Content unchanged — skip tree surgery and ref advance to
236						// avoid a no-op commit on /full/current. The existing ref
237						// already references the correct tree.
238						return nil
239					}
240				}
241			}
242		}
243	
244		// Clear existing transcript artifacts for this session path before writing new ones.
245		// Preserve non-transcript metadata under the same session (e.g., tasks/*).
246		for key := range entries {
247			switch {
248			case key == rawTranscriptPath:
249				delete(entries, key)
250			case strings.HasPrefix(key, rawTranscriptPath+"."):
251				delete(entries, key)
252			case key == rawHashPath:
253				delete(entries, key)
254			}
255		}
256	
257		if err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, precomputed, sessionPath, entries); err != nil {
258			return err
259		}
260	
261		if err := s.writeContentHashFromPrecompute(newContentHash, precomputed, sessionPath, entries); err != nil {
262			return err
263		}
264	
265		// Splice into existing root tree (preserves other checkpoints' transcripts)
266		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
267		if err != nil {
268			return err
269		}
270	
271		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
272		commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
273		return s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
274	}
