319	// writeMainCheckpointEntries orchestrates writing session data to the /main ref.
320	// It mirrors GitStore.writeStandardCheckpointEntries but excludes raw transcript blobs.
321	// Returns the session index used, for coordination with writeCommittedFullTranscript.
322	func (s *V2GitStore) writeMainCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (int, error) {
323		// Read existing summary to get current session count
324		var existingSummary *CheckpointSummary
325		metadataPath := basePath + paths.MetadataFileName
326		if entry, exists := entries[metadataPath]; exists {
327			existing, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
328			if err == nil {
329				existingSummary = existing
330			}
331		}
332	
333		// Determine session index
334		sessionIndex := s.gs.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
335	
336		// Refuse if slot 0 already holds metadata for a DIFFERENT session ID.
337		// Mirrors GitStore.writeStandardCheckpointEntries: findSessionIndex only
338		// picks slot 0 when existingSummary is nil or when the summary claims slot 0
339		// belongs to us, so the actual tree holding session-0 metadata for someone
340		// else is a corruption / stale-summary shape. Read BEFORE
341		// writeMainSessionToSubdirectory clears the subtree, or we'd only ever see
342		// our own write.
343		if sessionIndex == 0 {
344			if entry, exists := entries[fmt.Sprintf("%s0/%s", basePath, paths.MetadataFileName)]; exists {
345				if existingMeta, readErr := s.gs.readMetadataFromBlob(entry.Hash); readErr == nil && existingMeta.SessionID != opts.SessionID {
346					logging.Error(ctx, "refusing v2 checkpoint write: session 0 holds a different sessionID",
347						slog.String("checkpoint_id", opts.CheckpointID.String()),
348						slog.String("existing_session_id", existingMeta.SessionID),
349						slog.String("write_session_id", opts.SessionID),
350						slog.Bool("existing_summary_nil", existingSummary == nil))
351					return 0, fmt.Errorf(
352						"refusing to overwrite session 0 of checkpoint %s: existing session ID %q differs from write session ID %q. The v2 checkpoint tree is inconsistent (session 0 belongs to a different session than this write claims). No automated repair exists for this shape — please report it along with the output of `git ls-tree %s %s/`",
353						opts.CheckpointID, existingMeta.SessionID, opts.SessionID, paths.V2MainRefName, opts.CheckpointID.Path(),
354					)
355				}
356			}
357		}
358	
359		// Write session files (metadata and prompts — no transcript or content hash)
360		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
361		sessionFilePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
362		if err != nil {
363			return 0, err
364		}
365	
366		// Build the sessions array
367		var sessions []SessionFilePaths
368		if existingSummary != nil {
369			sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
370			copy(sessions, existingSummary.Sessions)
371		} else {
372			sessions = make([]SessionFilePaths, 1)
373		}
374		sessions[sessionIndex] = sessionFilePaths
375	
376		// Write root CheckpointSummary
377		if err := s.gs.writeCheckpointSummary(opts, basePath, entries, sessions); err != nil {
378			return 0, err
379		}
380		return sessionIndex, nil
381	}
382	
383	// writeMainSessionToSubdirectory writes a single session's metadata, prompts,
384	// and compact transcript to a session subdirectory (0/, 1/, 2/, … indexed by
385	// session order within the checkpoint). The raw transcript (raw_transcript) and its
386	// content hash (raw_transcript_hash.txt) go to /full/current, not here.
387	func (s *V2GitStore) writeMainSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
388		filePaths := SessionFilePaths{}
389	
390		// Clear existing entries at this session path
391		for key := range entries {
392			if strings.HasPrefix(key, sessionPath) {
393				delete(entries, key)
394			}
395		}
396	
397		// Write prompts
398		if len(opts.Prompts) > 0 {
399			promptContent := redact.String(JoinPrompts(opts.Prompts))
400			blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
401			if err != nil {
402				return filePaths, err
403			}
404			entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
405				Name: sessionPath + paths.PromptFileName,
406				Mode: filemode.Regular,
407				Hash: blobHash,
408			}
409			filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
410		}
411	
412		// Write compact transcript (transcript.jsonl) + hash if provided
413		if len(opts.CompactTranscript) > 0 {
414			blobHash, err := CreateBlobFromContent(s.repo, opts.CompactTranscript)
415			if err != nil {
416				return filePaths, fmt.Errorf("failed to create compact transcript blob: %w", err)
417			}
418			entries[sessionPath+paths.CompactTranscriptFileName] = object.TreeEntry{
419				Name: sessionPath + paths.CompactTranscriptFileName,
420				Mode: filemode.Regular,
421				Hash: blobHash,
422			}
423			filePaths.Transcript = "/" + sessionPath + paths.CompactTranscriptFileName
424	
425			if err := s.writeCompactTranscriptHash(opts.CompactTranscript, sessionPath, entries); err != nil {
426				return filePaths, fmt.Errorf("failed to write compact transcript hash: %w", err)
427			}
428			filePaths.ContentHash = "/" + sessionPath + paths.CompactTranscriptHashFileName
429		}
430	
431		// Write session metadata
432		sessionMetadata := CommittedMetadata{
433			CheckpointID:                opts.CheckpointID,
434			SessionID:                   opts.SessionID,
435			Strategy:                    opts.Strategy,
436			CreatedAt:                   time.Now().UTC(),
437			Branch:                      opts.Branch,
438			CheckpointsCount:            opts.CheckpointsCount,
439			FilesTouched:                opts.FilesTouched,
440			Agent:                       opts.Agent,
441			Model:                       opts.Model,
442			TurnID:                      opts.TurnID,
443			IsTask:                      opts.IsTask,
444			ToolUseID:                   opts.ToolUseID,
445			TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
446			CheckpointTranscriptStart:   opts.CompactTranscriptStart,
447			TokenUsage:                  opts.TokenUsage,
448			SessionMetrics:              opts.SessionMetrics,
449			InitialAttribution:          opts.InitialAttribution,
450			PromptAttributions:          opts.PromptAttributionsJSON,
451			Summary:                     redactSummary(opts.Summary),
452			CLIVersion:                  versioninfo.Version,
453		}
454	
455		metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
456		if err != nil {
457			return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
458		}
459		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
460		if err != nil {
461			return filePaths, err
462		}
463		entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
464			Name: sessionPath + paths.MetadataFileName,
465			Mode: filemode.Regular,
466			Hash: metadataHash,
467		}
468		filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
469	
470		return filePaths, nil
471	}
472	
473	// writeCompactTranscriptHash computes and writes the SHA-256 hash of the compact transcript.
474	func (s *V2GitStore) writeCompactTranscriptHash(compactTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
475		hash := fmt.Sprintf("sha256:%x", sha256.Sum256(compactTranscript))
476		blobHash, err := CreateBlobFromContent(s.repo, []byte(hash))
477		if err != nil {
478			return err
479		}
480		entries[sessionPath+paths.CompactTranscriptHashFileName] = object.TreeEntry{
481			Name: sessionPath + paths.CompactTranscriptHashFileName,
482			Mode: filemode.Regular,
483			Hash: blobHash,
484		}
485		return nil
486	}
487	
488	// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
489	// Transcripts accumulate across checkpoints — each write splices into the existing
490	// tree. Generation metadata (generation.json) at the tree root is updated on every
491	// write with the new checkpoint ID and timestamps.
492	//
493	// sessionIndex is the session slot (0-based), determined by the caller to stay
494	// consistent with the /main ref's session numbering.
495	// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
496	func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
497		transcript := opts.Transcript
498	
499		// TranscriptPath fallback: data read from disk is an untrusted source,
500		// so we redact it here. The in-memory path (opts.Transcript) is already
501		// pre-redacted by the caller.
502		if transcript.Len() == 0 && opts.TranscriptPath != "" {
503			rawData, readErr := os.ReadFile(opts.TranscriptPath)
504			if readErr != nil {
505				rawData = nil
506			}
507			if len(rawData) > 0 {
508				redacted, redactErr := redact.JSONLBytes(rawData)
509				if redactErr != nil {
510					return fmt.Errorf("failed to redact transcript from file: %w", redactErr)
511				}
512				transcript = redacted
513			}
514		}
515		if transcript.Len() == 0 {
516			return nil // No transcript to write
517		}
518	
519		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
520		if err := s.ensureRef(ctx, refName); err != nil {
521			return fmt.Errorf("failed to ensure /full/current ref: %w", err)
522		}
523	
524		parentHash, rootTreeHash, err := s.GetRefState(refName)
525		if err != nil {
526			return err
527		}
528	
529		basePath := opts.CheckpointID.Path() + "/"
530		checkpointPath := opts.CheckpointID.Path()
531		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
532	
533		// Read existing entries at this checkpoint's shard path
534		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
535		if err != nil {
536			return err
537		}
538	
539		// Clear existing entries at this session path before writing new ones
540		for key := range entries {
541			if strings.HasPrefix(key, sessionPath) {
542				delete(entries, key)
543			}
544		}
545	
546		if err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, nil, sessionPath, entries); err != nil {
547			return err
548		}
549	
550		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript.Bytes()))
551		if err := s.writeContentHashFromPrecompute(contentHash, nil, sessionPath, entries); err != nil {
552			return err
553		}
554	
555		// Splice checkpoint data into the root tree (preserves other checkpoints' transcripts)
556		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
557		if err != nil {
558			return err
559		}
560	
561		commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
562		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
563			return err
564		}
565	
566		// Check if rotation is needed after successful write.
567		// Count checkpoints by walking the tree (no generation.json on /full/current).
568		checkpointCount, countErr := s.CountCheckpointsInTree(newTreeHash)
569		if countErr != nil {
570			logging.Warn(ctx, "failed to count checkpoints for rotation check",
571				slog.String("error", countErr.Error()),
572			)
573			return nil
574		}
575		if checkpointCount >= s.maxCheckpoints() {
576			if rotErr := s.rotateGeneration(ctx); rotErr != nil {
577				logging.Warn(ctx, "generation rotation failed",
578					slog.String("error", rotErr.Error()),
579					slog.Int("checkpoint_count", checkpointCount),
580				)
581				// Non-fatal: rotation failure doesn't invalidate the write
582			}
583		}
584	
585		return nil
586	}
587	
588	// writeTranscriptBlobs writes pre-redacted, chunked transcript blobs to entries.
589	// When precomputed is non-nil, reuses its chunk blob hashes and skips both
590	// ChunkTranscript and CreateBlobFromContent.
591	func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript redact.RedactedBytes, agentType types.AgentType, precomputed *PrecomputedTranscriptBlobs, sessionPath string, entries map[string]object.TreeEntry) error {
592		var chunkHashes []plumbing.Hash
593		if precomputed != nil {
594			chunkHashes = precomputed.ChunkHashes
595		} else {
596			chunks, err := chunkTranscript(ctx, transcript.Bytes(), agentType)
597			if err != nil {
598				return fmt.Errorf("failed to chunk transcript: %w", err)
599			}
600			chunkHashes = make([]plumbing.Hash, len(chunks))
601			for i, chunk := range chunks {
602				h, err := CreateBlobFromContent(s.repo, chunk)
603				if err != nil {
604					return err
605				}
606				chunkHashes[i] = h
607			}
608		}
609	
610		for i, blobHash := range chunkHashes {
611			chunkPath := sessionPath + agent.ChunkFileName(paths.V2RawTranscriptFileName, i)
612			entries[chunkPath] = object.TreeEntry{
613				Name: chunkPath,
614				Mode: filemode.Regular,
615				Hash: blobHash,
616			}
617		}
618	
619		return nil
620	}
621	
622	// writeContentHashFromPrecompute writes the content-hash blob for the given
623	// transcript hash. When precomputed is non-nil, reuses its ContentHashBlob
624	// hash; otherwise creates a fresh blob.
625	func (s *V2GitStore) writeContentHashFromPrecompute(contentHash string, precomputed *PrecomputedTranscriptBlobs, sessionPath string, entries map[string]object.TreeEntry) error {
626		var hashBlob plumbing.Hash
627		if precomputed != nil {
628			hashBlob = precomputed.ContentHashBlob
629		} else {
630			h, err := CreateBlobFromContent(s.repo, []byte(contentHash))
631			if err != nil {
632				return err
633			}
634			hashBlob = h
635		}
636		entries[sessionPath+paths.V2RawTranscriptHashFileName] = object.TreeEntry{
637			Name: sessionPath + paths.V2RawTranscriptHashFileName,
638			Mode: filemode.Regular,
639			Hash: hashBlob,
640		}
641		return nil
642	}
643	
644	// validateWriteOpts validates identifiers in WriteCommittedOptions.
645	func validateWriteOpts(opts WriteCommittedOptions) error {
646		if opts.CheckpointID.IsEmpty() {
647			return errors.New("invalid checkpoint options: checkpoint ID is required")
648		}
649		if err := validation.ValidateSessionID(opts.SessionID); err != nil {
650			return fmt.Errorf("invalid checkpoint options: %w", err)
651		}
652		if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
653			return fmt.Errorf("invalid checkpoint options: %w", err)
654		}
655		if err := validation.ValidateAgentID(opts.AgentID); err != nil {
656			return fmt.Errorf("invalid checkpoint options: %w", err)
657		}
658		return nil
659	}
660	
661	// UpdateSummary persists an AI-generated summary into the latest session's
662	// metadata on the v2 /main ref. Mirrors GitStore.UpdateSummary for v1.
663	func (s *V2GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
664		if err := ctx.Err(); err != nil {
665			return err //nolint:wrapcheck // Propagating context cancellation
666		}
667	
668		refName := plumbing.ReferenceName(paths.V2MainRefName)
669		parentHash, rootTreeHash, err := s.GetRefState(refName)
670		if err != nil {
671			return ErrCheckpointNotFound
672		}
673	
674		basePath := checkpointID.Path() + "/"
675		checkpointPath := checkpointID.Path()
676		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
677		if err != nil {
678			return err
679		}
680	
681		rootMetadataPath := basePath + paths.MetadataFileName
682		entry, exists := entries[rootMetadataPath]
683		if !exists {
684			return ErrCheckpointNotFound
685		}
686	
687		cpSummary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
688		if err != nil {
689			return fmt.Errorf("failed to read checkpoint summary: %w", err)
690		}
691		if len(cpSummary.Sessions) == 0 {
692			return ErrCheckpointNotFound
693		}
694	
695		latestIndex := len(cpSummary.Sessions) - 1
696		sessionMetadataPath := fmt.Sprintf("%s%d/%s", basePath, latestIndex, paths.MetadataFileName)
697		sessionEntry, exists := entries[sessionMetadataPath]
698		if !exists {
699			return fmt.Errorf("session metadata not found at index %d", latestIndex)
700		}
701	
702		metadata, err := readJSONFromBlob[CommittedMetadata](s.repo, sessionEntry.Hash)
703		if err != nil {
704			return fmt.Errorf("failed to read session metadata: %w", err)
705		}
706		metadata.Summary = redactSummary(summary)
707	
708		metadataJSON, err := jsonutil.MarshalIndentWithNewline(metadata, "", "  ")
709		if err != nil {
710			return fmt.Errorf("failed to marshal metadata: %w", err)
711		}
712		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
713		if err != nil {
714			return fmt.Errorf("failed to create metadata blob: %w", err)
715		}
716		entries[sessionMetadataPath] = object.TreeEntry{
717			Name: sessionMetadataPath,
718			Mode: filemode.Regular,
719			Hash: metadataHash,
720		}
721	
722		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, checkpointID, basePath, entries)
723		if err != nil {
724			return err
725		}
726	
727		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
728		commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, metadata.SessionID)
729		return s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
730	}
